class LedgerDistributor:
    def distribute(self, total_cents: int, beneficiaries: list[Beneficiary]) -> dict[str, int]:
        if not beneficiaries or total_cents <= 0:
            return {b.name: 0 for b in beneficiaries}
        total_weight = sum(b.weight for b in beneficiaries)
        if total_weight == 0:
            return {b.name: 0 for b in beneficiaries}

        # Compute floor allocations and remainders using integer arithmetic
        floors = []
        remainders = []  # numerators of fractional parts
        for b in beneficiaries:
            product = total_cents * b.weight
            f = product // total_weight
            r = product % total_weight
            floors.append(f)
            remainders.append(r)

        allocated = sum(floors)
        remainder = total_cents - allocated  # number of cents left to distribute

        # If there is a remainder, distribute to those with largest fractional parts
        if remainder > 0:
            # Indices sorted by remainder descending (largest fractional part first)
            indices = sorted(range(len(beneficiaries)), key=lambda i: remainders[i], reverse=True)
            for i in range(remainder):
                floors[indices[i]] += 1

        return {beneficiaries[i].name: floors[i] for i in range(len(beneficiaries))}
}

