from source_layer import Layer

class ConfigMerger:
    def merge(self, default_cfg: dict, file_cfg: dict, env_cfg: dict, cli_cfg: dict) -> dict:
        result = {}
        result = self._deep_merge(result, default_cfg)
        result = self._deep_merge(result, file_cfg)
        result = self._deep_merge(result, env_cfg)
        result = self._deep_merge(result, cli_cfg)
        return result

    def _deep_merge(self, target: dict, source: dict) -> dict:
        """Recursively merge source dict into target dict, returning a new dict."""
        merged = {}
        for key in set(target.keys()) | set(source.keys()):
            if key in target and key in source:
                if isinstance(target[key], dict) and isinstance(source[key], dict):
                    merged[key] = self._deep_merge(target[key], source[key])
                else:
                    merged[key] = source[key]
            elif key in target:
                merged[key] = target[key]
            else:
                merged[key] = source[key]
        return merged

